-- Builds event_firm_state_pit2 (rule pit_v2), 2026-10-29. IDENTICAL to the v1 record (scripts/sql/event_firm_state_pit_v1_build.sql) except the availability date:
-- COALESCE(real filing date from sec_filings (10-Q or 10-K for that security and period_end), LEAST(stored filed_date, period_end + 90 days)).
-- Extra columns: stored_filed_date (what v1 used) and availability_source (real_filing or capped_stored). pit_v1 is untouched. Run once in the SQL editor.
CREATE TABLE event_firm_state_pit2 AS WITH rl AS MATERIALIZED (SELECT security_id, period_end, MIN(filing_date) AS real_date FROM sec_filings WHERE form_type IN ($$10-Q$$, $$10-K$$) GROUP BY 1, 2), q AS MATERIALIZED (SELECT f.security_id, f.period_end, f.composite_score, ((f.revenue_growth_change IS NOT NULL AND f.revenue_growth_change BETWEEN -5 AND 5)::int + (f.gross_margin_change IS NOT NULL AND f.gross_margin_change BETWEEN -5 AND 5)::int + (f.operating_margin_change IS NOT NULL AND f.operating_margin_change BETWEEN -5 AND 5)::int + (f.fcf_margin_change IS NOT NULL AND f.fcf_margin_change BETWEEN -5 AND 5)::int) AS n_terms, fs.filed AS stored_filed, COALESCE(r.real_date, LEAST(fs.filed, f.period_end + 90)) AS avail, CASE WHEN r.real_date IS NOT NULL THEN $$real_filing$$ ELSE $$capped_stored$$ END AS avail_source FROM financial_condition_score f JOIN (SELECT security_id, period_end, MIN(filed_date) AS filed FROM financial_statements GROUP BY 1, 2) fs ON fs.security_id = f.security_id AND fs.period_end = f.period_end LEFT JOIN rl r ON r.security_id = f.security_id AND r.period_end = f.period_end), pairs AS (SELECT p.event_id, p.entity_id, sec.id AS security_id, e.event_date::date AS event_day FROM event_pre_context p JOIN events e ON e.id = p.event_id JOIN securities sec ON sec.entity_id = p.entity_id), pit AS (SELECT DISTINCT ON (pr.event_id, pr.entity_id) pr.event_id, pr.entity_id, q.period_end, q.avail, q.stored_filed, q.avail_source, q.composite_score, q.n_terms FROM pairs pr LEFT JOIN q ON q.security_id = pr.security_id AND q.avail < pr.event_day ORDER BY pr.event_id, pr.entity_id, q.period_end DESC NULLS LAST), pe AS (SELECT DISTINCT ON (pr.event_id, pr.entity_id) pr.event_id, pr.entity_id, q.period_end AS pe_period_end, q.composite_score AS pe_score FROM pairs pr LEFT JOIN q ON q.security_id = pr.security_id AND q.period_end < pr.event_day ORDER BY pr.event_id, pr.entity_id, q.period_end DESC NULLS LAST) SELECT pr.event_id, pr.entity_id, pr.security_id, pr.event_day, pit.period_end, pit.avail AS filed_date, pit.stored_filed AS stored_filed_date, pit.avail_source AS availability_source, pit.composite_score, pit.n_terms, CASE WHEN pit.composite_score IS NULL THEN NULL WHEN pit.composite_score < -0.039247119206188 THEN $$deteriorating$$ WHEN pit.composite_score < -0.0078504471309634 THEN $$weakening$$ WHEN pit.composite_score < 0.00901847919266089 THEN $$stable$$ WHEN pit.composite_score < 0.040663412043068 THEN $$improving$$ ELSE $$strong$$ END AS state, pe.pe_period_end AS period_end_rule_period, CASE WHEN pe.pe_score IS NULL THEN NULL WHEN pe.pe_score < -0.039247119206188 THEN $$deteriorating$$ WHEN pe.pe_score < -0.0078504471309634 THEN $$weakening$$ WHEN pe.pe_score < 0.00901847919266089 THEN $$stable$$ WHEN pe.pe_score < 0.040663412043068 THEN $$improving$$ ELSE $$strong$$ END AS state_period_end_rule_today, $$pit_v2$$ AS rule_version, CURRENT_DATE AS computed_on FROM pairs pr JOIN pit ON pit.event_id = pr.event_id AND pit.entity_id = pr.entity_id JOIN pe ON pe.event_id = pr.event_id AND pe.entity_id = pr.entity_id;